// File: Models/User.cs
// Purpose: Defines the User domain entity for authentication and role-based
//          authorisation within the GLMS system. Stores a hashed password —
//          plain-text passwords must never be persisted.

using System.ComponentModel.DataAnnotations;

namespace GLMS.Core.Models;

/// <summary>
/// Represents an authenticated user of the GLMS system.
/// Used by the authentication pipeline to verify credentials and assign
/// role-based access (e.g. "Admin", "User").
/// </summary>
public class User
{
    /// <summary>
    /// Primary key generated by the database.
    /// </summary>
    public int Id { get; set; }

    /// <summary>
    /// Unique login name for the user. Must be non-empty and is limited to
    /// 100 characters to align with UI and token constraints.
    /// </summary>
    [Required]
    [MaxLength(100)]
    public string Username { get; set; } = string.Empty;

    /// <summary>
    /// BCrypt (or equivalent) hash of the user's password. Stored instead of
    /// the plain-text password to protect credentials at rest.
    /// </summary>
    [Required]
    public string PasswordHash { get; set; } = string.Empty;

    /// <summary>
    /// Role assigned to the user (e.g. "Admin", "User"). Used by authorisation
    /// middleware to gate access to protected endpoints.
    /// </summary>
    [Required]
    [MaxLength(50)]
    public string Role { get; set; } = string.Empty;
}
